create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default '',created_at timestamptz not null default now(),role text check(role in ('developer','security','engineering_leader')),primary_ide text check(primary_ide in ('vscode','cursor','windsurf','vscodium','other')),use_case text check(use_case in ('personal','team')),onboarding_completed boolean not null default false,updated_at timestamptz not null default now());
create table public.watchlists(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null default 'My extensions',created_at timestamptz not null default now());
create table public.watchlist_items(watchlist_id uuid not null references public.watchlists(id) on delete cascade,extension_id text not null references public.extensions(id) on delete cascade,created_at timestamptz not null default now(),primary key(watchlist_id,extension_id));
create table public.teams(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.team_members(team_id uuid not null references public.teams(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('owner','member')),primary key(team_id,user_id));
create table public.team_invitations(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.teams(id) on delete cascade,token_hash text unique not null,role text not null default 'member' check(role in ('owner','member')),expires_at timestamptz not null,accepted_at timestamptz,created_by uuid not null references auth.users(id));
create table public.team_watchlist_items(team_id uuid not null references public.teams(id) on delete cascade,extension_id text not null references public.extensions(id) on delete cascade,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),primary key(team_id,extension_id));
create table public.finding_triage(team_id uuid not null references public.teams(id) on delete cascade,scan_id uuid not null references public.scans(id) on delete cascade,finding_id text not null,status text not null check(status in ('open','reviewing','accepted_risk','resolved','false_positive')),assigned_to uuid references auth.users(id) on delete set null,updated_by uuid not null references auth.users(id),updated_at timestamptz not null default now(),primary key(team_id,scan_id,finding_id),foreign key(scan_id,finding_id) references public.findings(scan_id,id) on delete cascade);
create table public.finding_comments(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.teams(id) on delete cascade,scan_id uuid not null,finding_id text not null,author_id uuid not null references auth.users(id),body text not null check(char_length(body) between 1 and 4000),created_at timestamptz not null default now(),foreign key(team_id,scan_id,finding_id) references public.finding_triage(team_id,scan_id,finding_id) on delete cascade);
create table public.product_events(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,anonymous_id text,name text not null check(name in ('catalog_search','extension_view','scan_requested','scan_completed','account_created','watch_added','team_created','design_partner_submitted')),properties jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.design_partner_leads(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,name text not null,work_email text not null,company text not null,team_size text not null,current_process text not null,extension_count text not null,status text not null default 'new' check(status in ('new','contacted','qualified','closed')),created_at timestamptz not null default now());;
